"""Regenerate the offline worker bundle after changing its source files."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent
files = ('vendor/pako-inflate.min.js', 'vendor/utif.js', 'tiff-image.js',
         'viewer-background-values.js', 'pixel-worker.js')
source = 'self.__pixelWorkerBundled=true;self.window=self;self.__tiffWorkerContext=true;\n'
source += '\n;\n'.join((root / name).read_text(encoding='utf-8') for name in files)
(root / 'pixel-worker-source.js').write_text(
    '/* Generated by build-pixel-worker.py; do not edit directly. */\n'
    'window.PixelWorkerSource=' + json.dumps(source, ensure_ascii=True) + ';\n', encoding='utf-8')
